head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > useButton]<br/>calendarValueType='yearMonth' 일때 컴포넌트의 확인, 취소 버튼을 button 태그로 렌더링할지 설정합니다.",
    "validation" : [
        "calendarValueType='yearMonth' 일때 동작합니다.",
        "미설정(기본값 false) 시 확인, 취소 버튼을 div 태그로 렌더링합니다.",
        "true 설정 시 확인, 취소 버튼을 button 태그로 렌더링합니다.",
        "true 설정 시 CSS 클래스 'w2inputCalendar_header_btn_ok_div', 'w2inputCalendar_header_btn_close_div' 가 적용됩니다.",
        "false 설정 시 div 태그에 role='button' 과 tabindex='0' 이 부여됩니다.",
        "false 설정 시 텍스트 없이 CSS 배경 이미지 기반으로 표현됩니다.",
        "false 설정 시 CSS 클래스 'w2calendar_header_btn_ok', 'w2calendar_header_btn_close' 가 적용됩니다.",
        "확인 버튼은 skipConfirm=false 또는 skipConfirmOnly=true 일 때 표시됩니다.",
        "취소 버튼은 cancelButtonHide=false 일 때 표시됩니다.",
        "renderType 속성은 컴포넌트 전체 영역에서 button 태그와 div 태그 간의 렌더링 결정을 담당합니다.",
        "useButton 속성은 calendarValueType='yearMonth' 일때 Header 의 확인, 취소 버튼에만 영향을 줍니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // useButton 동작 조건: calendarValueType='yearMonth' 고정
    // 확인 버튼 표시: skipConfirm=false / 취소 버튼 표시: cancelButtonHide=false 고정
    let properties = {
        useButton : con_useButton.getText(),
        calendarValueType : "yearMonth",
        skipConfirm : "false",
        cancelButtonHide : "false"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList([]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [공통] 확인 버튼 DOM 정보 (tagName / role / tabindex / className / textContent)
// validation:
//  - useButton=true → <button class='w2inputCalendar_header_btn_ok_div'>
//  - useButton=false → <div class='w2calendar_header_btn_ok' role='button' tabindex='0' (텍스트 없음, 배경 이미지)>
//  - 확인 버튼은 skipConfirm=false 또는 skipConfirmOnly=true 일 때 표시
scwin.getConfirmButtonInfo = function () {
    let r = target1.render;
    let okBtn = r.querySelector('[class*="w2inputCalendar_header_btn_ok_div"]')
        || r.querySelector('[class*="w2calendar_header_btn_ok"]');

    if (!okBtn) {
        wf_body_bottom.getObj("scwin").setReturnValue("[확인 버튼 태그] 표시되지 않음 (skipConfirm/skipConfirmOnly 조건 미충족)");
        return;
    }

    let tagName = okBtn.tagName;
    let role = okBtn.getAttribute('role');
    let tabindex = okBtn.getAttribute('tabindex');
    let className = okBtn.className;
    let textContent = okBtn.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("[확인 버튼 태그] tagName=" + tagName
        + ", role=" + role
        + ", tabindex=" + tabindex
        + ", className='" + className + "'"
        + ", textContent='" + textContent + "'");
}



// [공통] 취소 버튼 DOM 정보 (tagName / role / tabindex / className / textContent)
// validation:
//  - useButton=true → <button class='w2inputCalendar_header_btn_close_div'>
//  - useButton=false → <div class='w2calendar_header_btn_close' role='button' tabindex='0' (텍스트 없음, 배경 이미지)>
//  - 취소 버튼은 cancelButtonHide=false 일 때 표시
scwin.getCloseButtonInfo = function () {
    let r = target1.render;
    let closeBtn = r.querySelector('[class*="w2inputCalendar_header_btn_close_div"]')
        || r.querySelector('[class*="w2calendar_header_btn_close"]');

    if (!closeBtn) {
        wf_body_bottom.getObj("scwin").setReturnValue("[취소 버튼 태그] 표시되지 않음 (cancelButtonHide=true)");
        return;
    }

    let tagName = closeBtn.tagName;
    let role = closeBtn.getAttribute('role');
    let tabindex = closeBtn.getAttribute('tabindex');
    let className = closeBtn.className;
    let textContent = closeBtn.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("[취소 버튼 태그] tagName=" + tagName
        + ", role=" + role
        + ", tabindex=" + tabindex
        + ", className='" + className + "'"
        + ", textContent='" + textContent + "'");
}



// 속성/DOM 정보 조회 버튼
scwin.btn_getInfo_onclick = function (e) {
    // validation: 확인 버튼 / 취소 버튼 DOM 정보
    scwin.getConfirmButtonInfo();
    scwin.getCloseButtonInfo();
}
